using System.Windows;using LabMaster.Services;namespace LabMaster;public partial class AnalyzerWindow:Window{readonly AnalyzerService service=new();public AnalyzerWindow(){InitializeComponent();Loaded+=async(_,_)=>await LoadAsync();}async Task LoadAsync(){try{var rows=await service.GetAsync();Grid.ItemsSource=rows;var due=rows.Count(x=>x.Active&&x.NextCalibration.HasValue&&x.NextCalibration.Value.Date<=DateTime.Today.AddDays(30));AlertText.Text=due==0?"No calibration due within 30 days.":$"⚠ {due} active analyzer(s) have calibration due within 30 days."; }catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}async void Add_Click(object s,RoutedEventArgs e){var w=new AddAnalyzerWindow{Owner=this};if(w.ShowDialog()==true)await LoadAsync();}async void Toggle_Click(object s,RoutedEventArgs e){if(Grid.SelectedItem is not AnalyzerRow a){MessageBox.Show("Select an analyzer.");return;}try{await service.SetActiveAsync(a.Id,!a.Active);await LoadAsync();}catch(Exception ex){MessageBox.Show(ex.Message,"Lab Master",MessageBoxButton.OK,MessageBoxImage.Error);}}}